COMMENT ON COLUMN cumplimiento.beneficiario_final.nombre IS '[NEGOCIO] Nombre descriptivo de la entidad para visualización y referencia en el sistema. [SISTEMA] varchar(150), obligatoria (NOT NULL).';
COMMENT ON COLUMN cumplimiento.beneficiario_final.documento IS '[NEGOCIO] Atributo que representa documento en el modelo de `beneficiario_final`. [SISTEMA] varchar(30), obligatoria (NOT NULL), sensibilidad PERSONAL.';
COMMENT ON COLUMN cumplimiento.beneficiario_final.porcentaje_participacion IS '[NEGOCIO] Tasa porcentual o alícuota aplicable a participacion. [SISTEMA] decimal(5,2), obligatoria (NOT NULL).';
COMMENT ON COLUMN cumplimiento.beneficiario_final.tipo_control IS '[NEGOCIO] Atributo que representa tipo control en el modelo de `beneficiario_final`. [SISTEMA] varchar(30), obligatoria (NOT NULL).';
COMMENT ON COLUMN cumplimiento.beneficiario_final.verificado IS '[NEGOCIO] Atributo que representa verificado en el modelo de `beneficiario_final`. [SISTEMA] boolean, obligatoria (NOT NULL).';
