COMMENT ON COLUMN cumplimiento.caso_investigacion_lft.estado IS '[NEGOCIO] Estado operativo o fase del ciclo de vida en que se encuentra el registro. [SISTEMA] varchar(15), obligatoria (NOT NULL), con índice B-tree.';
