COMMENT ON COLUMN cumplimiento.observacion_regulatoria.recibida_en IS '[NEGOCIO] Marca temporal o fecha de recibida en `observacion_regulatoria`. [SISTEMA] timestamptz, obligatoria (NOT NULL).';
