COMMENT ON COLUMN cumplimiento.activo_informacion.clasificacion IS '[NEGOCIO] Atributo que representa clasificacion en el modelo de `activo_informacion`. [SISTEMA] varchar(15), obligatoria (NOT NULL), con índice B-tree.';
