COMMENT ON COLUMN erp.tercero_comercial.estado IS '[NEGOCIO] Estado operativo o fase del ciclo de vida en que se encuentra el registro. [SISTEMA] varchar(15), obligatoria (NOT NULL), con índice B-tree.';
